 def test_shuffled_successors_and_all_historical_routes_keep_correct_wallet_files(self):self.fixture('valid')
 def test_current_pairing_cannot_be_rebound_to_another_device(self):self.fixture('bad-binding')
 def test_unconfigured_wallet_is_rejected_and_original_handles_are_closed(self):self.fixture('unconfigured')
